1	// configstore — print the effective service config with secret fields masked.
2	use serde_helper::{redact, to_line, version};
3	
4	fn main() {
5	    let database_url = "postgres://demo:PUBLIC_DEMO_PASSWORD@localhost:5432/configstore";
6	    let api_key = "PUBLIC_INVALID_DEMO_KEY";
7	
8	    println!(
9	        "# configstore {} (serde_helper {})",
10	        env!("CARGO_PKG_VERSION"),
11	        version()
12	    );
13	    println!("{}", to_line("database_url", database_url));
14	    // redact() masks the secret before it is printed (serde_helper >= 1.4.2).
15	    println!("{}", to_line("api_key", &redact(api_key)));
16	}
17
